function fixture(overrides={}) { const calls=[]; let allow=true, draftCount=0; const request=async(path,payload) => { calls.push({path,payload:clone(payload||null)}); if(path==='/catalog')return clone(catalog); if(path==='/design')return Object.assign(clone(design),{builder:payload.builder,custom_fields_design:clone(acf)}); if(path==='/region') return {region:{id:'region-'+calls.length,target:payload.target,start:payload.start,count:payload.count,source:payload.source,kind:payload.kind,label:payload.label,prototype:{native:[{type:'native'}],bindings:[],regions:[]}},fields:[{target:'/0/title',label:'Repeated heading',format:'text'}],containers:[{target:'/0/children',label:'Nested body',items:[{index:0,label:'Nested group'}]}],sources:[{path:'/title',label:'Section heading',kind:'text'},{path:'/children',label:'Nested sections',kind:'collection'}]}; if(path==='/preview')return {preview_document:{html:'<h1>Example</h1>'},preview_receipt:'receipt',summary:{sections:payload.input.content.sections.length}}; if(path==='/save') return {id:payload.id||'00000000-0000-4000-8000-000000000001',revision:payload.expected_revision+1,resource_id:payload.resource_id,default_saved:true,recipe:clone(payload.recipe)}; if(path==='/draft'){draftCount++; return {id:500,status:'draft',edit_url:'https://site.example/wp-admin/post.php?post=500',operation_id:payload.operation_id,reused:draftCount>1};} if(path.startsWith('/draft?'))return {id:500,status:'draft',edit_url:'https://site.example/wp-admin/post.php?post=500',reused:true}; throw Error('Unexpected '+path); }; const ctrl=ui.createController(Object.assign({request,confirm:()=>allow,uuid:()=> '00000000-0000-4000-8000-000000000999',origin:'https://site.example'},overrides)); return {ctrl,calls,setConfirm:value=>allow=value}; }
async function ready(f) { await f.ctrl.init(); assert.equal(f.ctrl.next(),true); await f.ctrl.capture(0); }
async function reviewed(f) { await ready(f); f.ctrl.next(); await f.ctrl.preview(); f.ctrl.next(); }
class Element {
 constructor(tag,document){this.tag=tag;this.ownerDocument=document;this.children=[];this.events={};this.attributes={};this.style={};this.value='';this.disabled=false;this.ownText='';this.className='';if(tag==='iframe'){const messages=[];this.contentWindow={messages,postMessage:(data,origin)=>messages.push({data:clone(data),origin})};}this.classList={add:name=>{this.className+=' '+name;},toggle:(name,on)=>{const names=this.className.split(' ').filter(value=>value&&value!==name);if(on)names.push(name);this.className=names.join(' ');}};}
 set textContent(value){this.ownText=String(value);this.children=[];}get textContent(){return this.ownText+this.children.map(child=>child.textContent).join(' ');}
 append(...children){children.forEach(child=>{child.parentNode=this;this.children.push(child);});}replaceChildren(...children){this.children=[];this.ownText='';this.append(...children);}setAttribute(key,value){this.attributes[key]=value;}addEventListener(key,callback){this.events[key]=callback;}all(){return[this,...this.children.flatMap(child=>child.all())];}
 querySelectorAll(selector){return this.all().filter(item=>item.tag===selector);}querySelector(selector){return selector==='.nlr-state'?this.all().find(item=>item.className.split(' ').includes('nlr-state')):null;}
}
async function mounted(settings={}){const document={createElement:tag=>new Element(tag,document)},host=new Element('div',document),f=fixture(),data=new Map(),listeners={};document.defaultView={location:{origin:'https://site.example',href:'https://site.example/wp-admin/options-general.php?page=nova-settings&tab=layout-recipes'},confirm:()=>true,addEventListener:(type,handler)=>{listeners[type]=handler;},sessionStorage:{getItem:key=>data.get(key)||null,setItem:(key,value)=>data.set(key,value),removeItem:key=>data.delete(key)}};const controller=ui.mount(host,{url:'/mapping/layout-recipes',nonce:'test',layoutsUrl:'https://site.example/wp-admin/layouts',...(settings.config||{})},{request:async(path,payload)=>{f.calls.push({path,payload:clone(payload||null)});if(settings.request)return settings.request(path,payload);if(path==='/catalog')return clone(catalog);if(path==='/design')return {...clone(design),custom_fields_design:clone(acf)};if(path==='/preview')return {preview_document:{html:'<h1>Safe structure</h1>'},preview_receipt:'receipt'};if(path==='/save')return {id:'00000000-0000-4000-8000-000000000001',revision:payload.expected_revision+1,resource_id:payload.resource_id,default_saved:true,recipe:clone(payload.recipe)};if(path.startsWith('/draft?operation_id='))return {id:511,status:'draft',operation_id:decodeURIComponent(path.split('=')[1]),edit_url:'https://site.example/wp-admin/post.php?post=511',view_url:'https://site.example/review-511?preview=true',reused:true};throw Error('Unexpected '+path);},uuid:()=> '00000000-0000-4000-8000-000000000999'});await controller.ready;return {controller,host,calls:f.calls,listeners,window:document.defaultView};}
function visualDesign(){const definition=[['heading','heading','title','Page heading','html','Existing page heading'],['intro','text-editor','editor','Intro text','html','<p>The original introduction.</p>'],['button','button','text','Button text','text','Get advice'],['button','button','link/url','Button link','url','https://site.example/contact/'],['body','text-editor','editor','Main rich text','html','<h2>Existing detail</h2><p>'+('Complete original paragraph. '.repeat(80))+'</p>']];const blueprint={document:[{id:'heading',elType:'widget',widgetType:'heading',settings:{title:definition[0][5],header_size:'h1'},elements:[]},{id:'intro',elType:'widget',widgetType:'text-editor',settings:{editor:definition[1][5]},elements:[]},{id:'button',elType:'widget',widgetType:'button',settings:{text:definition[2][5],link:{url:definition[3][5]}},elements:[]},{id:'body',elType:'widget',widgetType:'text-editor',settings:{editor:definition[4][5]},elements:[]}],meta:{background:'#8511D9'}};const fields=definition.map((entry,index)=>({field_id:'field_'+index,target:'/document/'+(index>2?index-1:index)+'/settings/'+entry[2],label:entry[3],format:entry[4],kind:entry[1],writable:true,value:entry[5],current_value:entry[5],example:entry[5].replace(/<[^>]+>/g,'').slice(0,160),locator:{strategy:'elementor',reference_id:42,node_id:entry[0],control_path:entry[2].split('/'),element_type:entry[1]}}));fields[3].target='/document/2/settings/link/url';fields[4].target='/document/3/settings/editor';fields.push({field_id:'static_map',target:'/document/4/settings/address',label:'Map location',format:'text',writable:false,protected:true,reason:'This native map control stays static.'});const source_reference={resource_id:'post_type:page',reference_type:'post',reference_id:42,title:'Real sample page',url:'https://site.example/real-sample/',builder:'elementor',native_digest:'a'.repeat(64)};return {builder:'elementor',blueprint,seal:'native-design-seal',fields,containers:[],sources:source,sample:{},recipe_preset:{format:'nova-layout-recipe/v1',builder:'elementor',mode:'mixed',blueprint:clone(blueprint),bindings:[],regions:[],instructions:''},source_reference,source_receipt:'signed-source',visual_preview:{status:'available',url:'https://site.example/real-sample/?nova_recipe_canvas=test',session_id:'00000000-0000-4000-8000-000000000042',digest:source_reference.native_digest,reference_id:42,reference_type:'post'},preview_fields:clone(fields)};}
