 await test('source receipt changes invalidate reviewed content without inventing a fresh reference',async()=>{const t=await visualMounted();t.controller.next();await t.controller.capture(42);choosePurpose(t,'title');t.controller.next();await t.controller.preview();const prior=t.controller.state.previewSignature;t.controller.edit(state=>{state.design.source_receipt='a newly inspected source receipt';});assert.notEqual(ui.previewKey(t.controller.state),prior);assert.equal(t.controller.canStep(5),false);await t.controller.save();assert.equal(t.calls.filter(item=>item.path==='/save').length,0);const unsafe=clone(t.design);unsafe.visual_preview.url='https://external.example/frame';assert.equal(ui.visualContext(unsafe,t.window.location.origin),null);unsafe.visual_preview.url=t.design.visual_preview.url;unsafe.visual_preview.digest='different-native-document';assert.equal(ui.visualContext(unsafe,t.window.location.origin),null);});
 await test('decoded compound native controls seed editorial examples without rewriting their raw carrier',async()=>{const packed='url:https%3A%2F%2Fsite.example%2Fcontact%2F|title:Keep%20this%20title|target:_blank',native={document:[{tag:'vc_btn',attributes:{link:packed},content:''}]},field={field_id:'packed_link',target:'/document/0/attributes/link',label:'Button link URL',format:'url',kind:'link_url',writable:true,current_value:'https://site.example/contact/',value:'https://site.example/contact/',example:'https://site.example/contact/'};const t=await visualMounted({request:async(path,payload,current,choices)=>{if(path==='/catalog'){choices.builders.push({id:'wpbakery',label:'WPBakery',available:true,modes:['static','mixed','rules'],capture:true,starter:true});return choices;}if(path==='/design')return {...clone(current),builder:'wpbakery',blueprint:clone(native),fields:[clone(field)],source_reference:{...clone(current.source_reference),builder:'wpbakery'},preview_fields:[],recipe_preset:{format:'nova-layout-recipe/v1',mode:'mixed',builder:'wpbakery',blueprint:clone(native),bindings:[],regions:[],instructions:''}};}});t.controller.next();await t.controller.capture(42);choosePurpose(t,'link_url');const binding=t.controller.state.recipe.bindings[0];t.controller.next();assert.equal(ui.contentValue(t.controller.state.content,binding.source),field.current_value);assert.equal(t.controller.state.recipe.blueprint.document[0].attributes.link,packed);await t.controller.preview();assert.equal(ui.contentValue(t.calls.find(item=>item.path==='/preview').payload.input.content,binding.source),field.current_value);const nested={bindings:[],regions:[{id:'urls',source:'/sections',kind:'repeat',prototype:{native:[{link:packed}],bindings:[{target:'/0/link',source:'/url',format:'url',required:true}],regions:[]}}]};const sample=ui.seedScope(nested,2,0,{}, {fields:[],regionMeta:{urls:{fields:[{target:'/0/link',format:'url',current_value:field.current_value}]}}});assert.deepEqual(sample.sections.map(item=>item.url),[field.current_value,field.current_value]);assert.equal(nested.regions[0].prototype.native[0].link,packed);});
 await test('manual ACF examples prefer declared constrained samples but retain valid captured rich text',async()=>{const original='<p>Keep the complete captured introduction.</p>',fields=[{target:'/document/count',label:'Quantity',format:'number',kind:'number',writable:true,current_value:'',sample:10,constraints:{type:'number',minimum:10,maximum:20}},{target:'/document/email',label:'Contact email',format:'text',kind:'email',writable:true,current_value:'',sample:'example@example.com',constraints:{type:'string',format:'email'}},{target:'/document/date',label:'Delivery date',format:'text',kind:'date_picker',writable:true,current_value:'',sample:'20260101',constraints:{type:'string'}},{target:'/document/style',label:'Presentation',format:'text',kind:'select',writable:true,current_value:'retired',sample:'wide',constraints:{type:'string',enum:['narrow','wide']}},{target:'/document/body',label:'Introduction',format:'html',kind:'wysiwyg',writable:true,current_value:original,sample:'<p>A generic fallback.</p>',constraints:{type:'string'}},{target:'/document/tagline',label:'Short promise',format:'text',kind:'text',writable:true,current_value:'x',sample:'A valid promise',constraints:{type:'string',minLength:8,maxLength:30}}],custom={builder:'acf',blueprint:{document:{count:'',email:'',date:'',style:'retired',body:original,tagline:'x',rows:[{count:''}]}},seal:'acf-constrained',fields,containers:[],sources:source,recipe_preset:{format:'nova-layout-recipe/v1',builder:'acf',mode:'mixed',blueprint:{document:{count:'',email:'',date:'',style:'retired',body:original,tagline:'x',rows:[{count:''}]}},bindings:[],regions:[],instructions:''}};const t=await visualMounted({request:async(path,payload,current)=>{if(path==='/design')return {...clone(current),custom_fields_design:clone(custom)};}});t.controller.next();await t.controller.capture(42);await t.controller.includeCustom(true);t.controller.edit(state=>{state.recipe.custom_fields.bindings=fields.map((item,index)=>({target:item.target,source:'/custom/acf_'+index,format:item.format,required:false,label:item.label}));state.recipe.custom_fields.regions=[{id:'acf_rows',target:'/document/rows',start:0,count:1,source:'/custom/rows',kind:'repeat',empty:'remove',max_items:20,prototype:{native:[{count:''}],bindings:[{target:'/0/count',source:'/quantity',format:'number',required:false,label:'Row quantity'}],regions:[]}}];state.regionMeta.acf_rows={fields:[{...clone(fields[0]),target:'/0/count'}],containers:[],sources:[]};});const native=clone(t.controller.state.recipe.custom_fields.blueprint);t.controller.next();assert.deepEqual(fields.map((item,index)=>ui.contentValue(t.controller.state.content,'/custom/acf_'+index)),[10,'example@example.com','20260101','wide',original,'A valid promise']);assert.deepEqual(t.controller.state.content.custom.rows.map(row=>row.quantity),[10,10]);const add=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Add content item');assert(add);add.events.click();assert.deepEqual(t.controller.state.content.custom.rows.map(row=>row.quantity),[10,10,10]);await t.controller.preview();assert.equal(t.controller.state.error,false);const supplied=t.calls.find(item=>item.path==='/preview').payload.input.content;assert.equal(supplied.custom.acf_0,10);assert.equal(supplied.custom.acf_4,original);assert.deepEqual(t.controller.state.recipe.custom_fields.blueprint,native);const overridden=ui.seedScope(t.controller.state.recipe.custom_fields,2,0,{custom:{acf_0:17,acf_1:'existing@site.example',acf_2:'20260202',acf_3:'narrow',acf_4:original,acf_5:'A human choice'}},{fields,regionMeta:t.controller.state.regionMeta});assert.equal(overridden.custom.acf_0,17);assert.equal(overridden.custom.acf_1,'existing@site.example');assert.equal(overridden.custom.acf_4,original);assert.equal(overridden.custom.acf_5,'A human choice');});
 await test('an ambiguous example can use an explicit provider while Automatic remains the main capture path',async()=>{const t=await visualMounted({request:async(path,payload,current)=>{if(path==='/design'){if(payload.builder==='auto')throw Error('This example has multiple providers. Choose its builder explicitly.');assert.equal(payload.builder,'acf');return {...clone(current),builder:'acf',source_reference:{...clone(current.source_reference),builder:'acf'},preview_fields:[],fields:clone(acf.fields),blueprint:clone(acf.blueprint),recipe_preset:{format:'nova-layout-recipe/v1',mode:'mixed',builder:'acf',blueprint:clone(acf.blueprint),bindings:[],regions:[]}};}}});t.controller.next();assert.equal(controlFor(t,'Builder detection').value,'auto');const picker=controlFor(t,'Reference item');picker.value='42';picker.events.change();let action=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Use this existing page');action.events.click();await new Promise(resolve=>setImmediate(resolve));assert.equal(t.controller.state.step,2);assert.equal(t.controller.state.design,null);assert(t.host.textContent.includes('multiple providers'));const detection=controlFor(t,'Builder detection');detection.value='acf';detection.events.change();action=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Use this existing page');action.events.click();await new Promise(resolve=>setImmediate(resolve));assert.deepEqual(t.calls.filter(item=>item.path==='/design').map(item=>item.payload.builder),['auto','acf']);assert.equal(t.controller.state.builder,'acf');assert.equal(t.controller.state.step,3);assert.deepEqual(t.controller.state.recipe.bindings,[]);assert(t.calls.every(item=>['/catalog','/design'].includes(item.path)));const before=t.calls.length;await t.controller.capture(42,'not-a-provider');assert.equal(t.calls.length,before);});
 await test('desktop and mobile use actual fixed viewports scaled to fit without remounting the reference',async()=>{const t=await visualMounted();t.controller.next();await t.controller.capture(42);const frame=t.host.all().find(item=>item.tag==='iframe'),body=t.host.all().find(item=>item.className==='nlr-canvas-body');body.clientWidth=816;t.listeners.resize();assert.equal(frame.style.width,'1440px');assert.equal(frame.style.height,'900px');assert.equal(frame.style.transform,'scale('+800/1440+')');assert.equal(body.style.height,(900*800/1440+16)+'px');assert(t.host.textContent.includes('Desktop reference · 1440 px'));let mobile=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Mobile reference · 390 px');mobile.events.click();assert.equal(frame.style.width,'390px');assert.equal(frame.style.height,'760px');assert.equal(frame.style.transform,'scale(1)');assert.equal(t.host.all().find(item=>item.tag==='iframe'),frame);body.clientWidth=336;t.listeners.resize();assert.equal(frame.style.width,'390px');assert.equal(frame.style.transform,'scale('+320/390+')');const desktop=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Desktop reference · 1440 px');desktop.events.click();assert.equal(frame.style.width,'1440px');assert.equal(frame.style.transform,'scale('+320/1440+')');assert.equal(t.host.all().find(item=>item.tag==='iframe'),frame);assert.equal(ui.referenceGeometry(1000,'desktop',1800).width,1800);assert.equal(ui.referenceGeometry(1000,'desktop',900).width,1440);assert.equal(t.calls.filter(item=>item.path==='/design').length,1);assert.equal(t.controller.state.recipe.bindings.length,0);});
